import type { Option } from "effect";
import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const {
  CompletedApplyScroll,
  MeasuredContainer,
  Message,
  Model,
  ScrolledContainer,
  init,
  scrollToIndex,
  scrollToIndexVariable,
  subscriptions,
  update,
  view,
  visibleWindow,
  visibleWindowVariable,
} = Ui.VirtualList;

export type CompletedApplyScroll = typeof CompletedApplyScroll.Type;
export type InitConfig = Ui.VirtualList.InitConfig;
export type MeasuredContainer = Ui.VirtualList.MeasuredContainer;
export type Message = Ui.VirtualList.Message;
export type Model = Ui.VirtualList.Model;
export type ScrolledContainer = Ui.VirtualList.ScrolledContainer;
export type ViewInputs<Item> = Ui.VirtualList.ViewInputs<Item>;
export type VisibleWindow = Ui.VirtualList.VisibleWindow;

export type InitReturn = readonly [Model, readonly Command.Command<Message>[]];
export type UpdateReturn = readonly [
  Model,
  readonly Command.Command<Message>[],
];
export type VisibleWindowReturn = Option.Option<VisibleWindow>;

export {
  activityListContainerClassName,
  activityListHeaderClassName,
  activityRow,
  activityRows,
  activitySummaryFor,
  activityVariableRow,
  activityVariableRowHeightPx,
  virtualListActionClassName,
} from "./view";
export type { Activity, ActivitySummary } from "./view";

import { Array, Match as M, Option, pipe } from "effect";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

export type Activity = Readonly<{
  id: number;
  actor: string;
  initial: string;
  colorClass: string;
  verb: string;
  target: string;
  timeAgo: string;
  hasSummary: boolean;
}>;

export type ActivitySummary = Readonly<{
  title: string;
  body: string;
  artifact: string;
}>;

const actorNames = [
  "Sarah Chen",
  "Marcus Davies",
  "Priya Patel",
  "Alex Kim",
  "Jordan Lee",
  "Sam Rivera",
  "Ben Carter",
  "Mira Patel",
  "Lucy Hong",
  "Casey Park",
  "Robin Adams",
  "Tomas Reyes",
];

const actionVerbs = [
  "merged",
  "opened",
  "commented on",
  "approved",
  "closed",
  "reopened",
  "requested review on",
  "pushed to",
];

const colorClasses = [
  "bg-rose-500",
  "bg-amber-500",
  "bg-emerald-500",
  "bg-sky-500",
  "bg-violet-500",
  "bg-fuchsia-500",
  "bg-teal-500",
  "bg-orange-500",
];

const branchNames = [
  "main",
  "feat/scroll-handlers",
  "fix/dialog-focus",
  "refactor/auth",
  "chore/deps",
];

const summaries: readonly ActivitySummary[] = [
  {
    title: "CI passing across all browsers",
    body: "Resolved the flake in the snapshot suite and confirmed the migration step runs idempotently against staging.",
    artifact: "ci/run-4892",
  },
  {
    title: "Tracking upstream change",
    body: "Linked the upstream regression and added reproduction context for the next reviewer.",
    artifact: "tracker/issue-218",
  },
  {
    title: "Release notes ready",
    body: "Bumped the patch version, regenerated the changelog, and queued the notes for editorial pass.",
    artifact: "release/v0.42.1",
  },
  {
    title: "Rollback plan coordinated",
    body: "Walked through the unwind steps with on-call and staged the revert PR.",
    artifact: "runbook/rollback",
  },
];

const cycle = (xs: readonly string[], index: number): string =>
  pipe(xs, Array.get(index % xs.length), Option.getOrThrow);

const formatTimeAgo = (hours: number): string => {
  if (hours < 1) {
    return `${Math.max(1, Math.round(hours * 60))}m ago`;
  }

  if (hours < 24) {
    return `${Math.round(hours)}h ago`;
  }

  const days = hours / 24;

  if (days < 30) {
    return `${Math.round(days)}d ago`;
  }

  const months = days / 30;

  if (months < 12) {
    return `${Math.round(months)}mo ago`;
  }

  return `${Math.round(months / 12)}y ago`;
};

const targetForVerb = (verb: string, index: number): string => {
  const number = ((index * 13) % 9999) + 1;

  return M.value(verb).pipe(
    M.withReturnType<string>(),
    M.when("pushed to", () => cycle(branchNames, index)),
    M.whenOr("opened", "closed", "reopened", () => `issue #${number}`),
    M.orElse(() => `PR #${number}`)
  );
};

export const activityRows = (count: number): readonly Activity[] =>
  Array.makeBy(count, (index) => {
    const actor = cycle(actorNames, index);
    const verb = cycle(actionVerbs, index);

    return {
      id: index,
      actor,
      initial: actor.charAt(0),
      colorClass: cycle(colorClasses, index),
      verb,
      target: targetForVerb(verb, index),
      timeAgo: formatTimeAgo(index * 2.3),
      hasSummary: index % 4 === 0,
    };
  });

export const activitySummaryFor = (index: number): ActivitySummary =>
  pipe(summaries, Array.get(index % summaries.length), Option.getOrThrow);

export const activityVariableRowHeightPx = (activity: Activity): number =>
  activity.hasSummary ? 112 : 56;

export const activityListContainerClassName =
  "h-80 w-full rounded-lg bg-white ring-1 ring-gray-200 overscroll-none";

export const activityListHeaderClassName =
  "flex items-end justify-between gap-4 text-sm text-gray-600";

export const virtualListActionClassName =
  "rounded bg-accent-600 px-3 py-1.5 text-sm font-medium text-white shadow-sm transition hover:bg-accent-700 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600 focus-visible:ring-offset-2";

const rowClassName =
  "grid grid-cols-[2rem_1fr_5rem] items-center gap-3 border-b border-gray-100 px-4";

const tallRowClassName =
  "grid grid-cols-[2rem_1fr_5rem] items-center gap-3 border-b border-gray-100 px-4 py-3";

const avatarClassName = (colorClass: string): string =>
  `${colorClass} flex h-7 w-7 items-center justify-center rounded-full text-xs font-semibold text-white`;

const activityTextClassName = "truncate text-sm text-gray-700";
const actorClassName = "font-semibold text-gray-900";
const targetClassName = "font-mono text-gray-900";
const timeAgoClassName = "text-right text-xs text-gray-500 tabular-nums";
const summaryTitleClassName = "mt-0.5 text-xs font-semibold text-gray-700";
const summaryBodyClassName =
  "mt-0.5 truncate text-xs leading-tight text-gray-500";
const artifactClassName =
  "mt-1 inline-flex w-fit rounded bg-gray-100 px-1.5 py-0.5 font-mono text-[10px] text-gray-600";

export const activityRow = (row: Activity): Html => {
  const h = html();

  return h.div(
    [h.Class(rowClassName)],
    [
      h.div([h.Class(avatarClassName(row.colorClass))], [row.initial]),
      h.div(
        [h.Class(activityTextClassName)],
        [
          h.span([h.Class(actorClassName)], [row.actor]),
          " ",
          row.verb,
          " ",
          h.span([h.Class(targetClassName)], [row.target]),
        ]
      ),
      h.div([h.Class(timeAgoClassName)], [row.timeAgo]),
    ]
  );
};

export const activityVariableRow = (
  row: Activity,
  summary: ActivitySummary
): Html => {
  const h = html();

  if (!row.hasSummary) {
    return activityRow(row);
  }

  return h.div(
    [h.Class(tallRowClassName)],
    [
      h.div([h.Class(avatarClassName(row.colorClass))], [row.initial]),
      h.div(
        [h.Class("min-w-0")],
        [
          h.div(
            [h.Class(activityTextClassName)],
            [
              h.span([h.Class(actorClassName)], [row.actor]),
              " ",
              row.verb,
              " ",
              h.span([h.Class(targetClassName)], [row.target]),
            ]
          ),
          h.div([h.Class(summaryTitleClassName)], [summary.title]),
          h.div([h.Class(summaryBodyClassName)], [summary.body]),
          h.div([h.Class(artifactClassName)], [summary.artifact]),
        ]
      ),
      h.div([h.Class(timeAgoClassName)], [row.timeAgo]),
    ]
  );
};

import { Effect, Option, Schema as S } from "effect";
import { Command, Scene, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, expect, test } from "vitest";

import * as VirtualList from "./index";

const listId = "registry-virtual-list";
const rows = VirtualList.activityRows(100);

const GotVirtualListMessage = m("GotVirtualListMessage", {
  message: VirtualList.Message,
});
const ClickedJumpToMiddle = m("ClickedJumpToMiddle");

const Model = S.Struct({
  virtualList: VirtualList.Model,
});
type Model = typeof Model.Type;

const Message = S.Union([GotVirtualListMessage, ClickedJumpToMiddle]);
type Message = typeof Message.Type;

const initialModel: Model = {
  virtualList: VirtualList.init({ id: listId, rowHeightPx: 56 }),
};
const [measuredVirtualList] = VirtualList.update(
  initialModel.virtualList,
  VirtualList.MeasuredContainer({ containerHeight: 224 })
);
const measuredModel: Model = {
  virtualList: measuredVirtualList,
};

const toParentMessage = (message: VirtualList.Message): Message =>
  GotVirtualListMessage({ message });

type ApplyScrollCommand = Readonly<{
  name: string;
  args: Record<string, unknown>;
  effect: Effect.Effect<VirtualList.CompletedApplyScroll>;
}>;

const applyScrollCommand = (
  id: string,
  scrollTop: number,
  version: number
): ApplyScrollCommand => {
  const result = VirtualList.CompletedApplyScroll({ version });

  return {
    name: "ApplyScroll",
    args: { id, scrollTop, version },
    effect: Effect.succeed(result),
  };
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] => {
  if (message._tag === "ClickedJumpToMiddle") {
    const [virtualList, commands] = VirtualList.scrollToIndex(
      model.virtualList,
      50
    );

    return [
      evo(model, { virtualList: () => virtualList }),
      Command.mapMessages(commands, toParentMessage),
    ];
  }

  const [virtualList, commands] = VirtualList.update(
    model.virtualList,
    message.message
  );

  return [
    evo(model, { virtualList: () => virtualList }),
    Command.mapMessages(commands, toParentMessage),
  ];
};

const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [],
    [
      h.button([h.OnClick(ClickedJumpToMiddle())], ["Jump to middle"]),
      h.submodel({
        slotId: model.virtualList.id,
        model: model.virtualList,
        view: VirtualList.view<VirtualList.Activity>(),
        viewInputs: {
          items: rows,
          itemToKey: (row) => String(row.id),
          itemToView: (row) => VirtualList.activityRow(row),
          containerClassName: VirtualList.activityListContainerClassName,
        },
        toParentMessage,
      }),
    ]
  );
});

describe("VirtualList registry view", () => {
  test("renders measured rows and applies programmatic scroll commands", () => {
    Scene.scene(
      { update, view },
      Scene.with(measuredModel),
      Scene.expect(Scene.text("Sarah Chen")).toExist(),
      Scene.click(Scene.role("button", { name: "Jump to middle" })),
      Scene.Command.resolve(
        applyScrollCommand(listId, 2800, 1),
        VirtualList.CompletedApplyScroll({ version: 1 }),
        toParentMessage
      )
    );
  });

  test("computes fixed and variable visible windows", () => {
    const [measured] = VirtualList.update(
      initialModel.virtualList,
      VirtualList.MeasuredContainer({ containerHeight: 112 })
    );
    const [scrolled] = VirtualList.update(
      measured,
      VirtualList.ScrolledContainer({ scrollTop: 112 })
    );

    expect(
      Option.getOrThrow(VirtualList.visibleWindow(scrolled, rows.length, 0))
    ).toEqual({
      startIndex: 2,
      endIndex: 4,
      topSpacerHeight: 112,
      bottomSpacerHeight: 5376,
    });
    expect(
      Option.getOrThrow(
        VirtualList.visibleWindowVariable(
          scrolled,
          rows,
          VirtualList.activityVariableRowHeightPx,
          0
        )
      )
    ).toEqual({
      startIndex: 1,
      endIndex: 3,
      topSpacerHeight: 112,
      bottomSpacerHeight: 6776,
    });
  });
});
